export async function requireUploadAccess(){
 const clean=new URL(location.href);clean.searchParams.delete('key');if(clean.hash.includes('key='))clean.hash='';history.replaceState(null,'',clean.pathname+clean.search+clean.hash);sessionStorage.removeItem('voice-record-key');
 const state=await fetch('/api/upload/session',{cache:'no-store'});if(!state.ok)throw Error('上传服务暂时无法连接，请刷新重试。');if((await state.json()).authenticated)return;
 await new Promise(resolve=>{const dialog=document.createElement('dialog');dialog.className='upload-login';dialog.innerHTML='<form><h2>上传空间</h2><p>输入密码后，可上传照片、音视频和录音。</p><label for="upload-password">密码</label><input id="upload-password" type="password" autocomplete="current-password" required><p class="login-error" role="status"></p><button type="submit">进入</button></form>';document.body.append(dialog);dialog.addEventListener('cancel',e=>e.preventDefault());dialog.showModal();dialog.querySelector('input').focus();dialog.querySelector('form').onsubmit=async e=>{e.preventDefault();const button=dialog.querySelector('button');button.disabled=true;try{const r=await fetch('/api/upload/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({password:dialog.querySelector('input').value})});const d=await r.json();if(!r.ok)throw Error(d.error||'登录失败');dialog.querySelector('input').value='';dialog.close();dialog.remove();resolve();}catch(error){dialog.querySelector('.login-error').textContent=error.message;}finally{button.disabled=false;}};});
}
